// Domino is a pair of values.
type Domino [2]int

func MakeChain(input []Domino) ([]Domino, bool) {
    n := len(input)
    if n == 0 {
        return []Domino{}, true
    }
    // Quick even-degree check as a fast rejection.
    degree := make(map[int]int)
    for _, d := range input {
        degree[d[0]]++
        degree[d[1]]++
    }
    for _, v := range degree {
        if v%2 != 0 {
            return []Domino{}, false
        }
    }
    // Backtracking search.
    chain := make([]Domino, 0, n)
    used := make([]bool, n)
    var found bool
    var search func(next int)
    search = func(next int) {
        if found {
            return
        }
        if len(chain) == n {
            if chain[0][0] == chain[n-1][1] {
                found = true
            }
            return
        }
        for i := range input {
            if used[i] {
                continue
            }
            d := input[i]
            // Try both orientations.
            for _, dd := range [2]Domino{{d[0], d[1]}, {d[1], d[0]}} {
                if dd[0] != next {
                    continue
                }
                used[i] = true
                chain = append(chain, dd)
                search(dd[1])
                chain = chain[:len(chain)-1]
                used[i] = false
                if found {
                    return
                }
            }
        }
    }
    // Start with each domino in each orientation.
    for i := range input {
        d := input[i]
        for _, dd := range [2]Domino{{d[0], d[1]}, {d[1], d[0]}} {
            used[i] = true
            chain = append([]Domino{}, dd)
            search(dd[1])
            chain = chain[:0]
            used[i] = false
            if found {
                return chain, true
            }
        }
    }
    return []Domino{}, false
}
